def shade(cell,fill):
    tcPr=cell._tc.get_or_add_tcPr();el=OxmlElement('w:shd');el.set(qn('w:fill'),fill);tcPr.append(el)


def word_sops():
    doc=Document();sec=doc.sections[0];sec.page_width=Cm(21);sec.page_height=Cm(29.7)
    sec.top_margin=Cm(1.6);sec.bottom_margin=Cm(1.6);sec.left_margin=Cm(1.7);sec.right_margin=Cm(1.7)
    normal=doc.styles['Normal'];normal.font.name='Arial';normal.font.size=Pt(10);normal.paragraph_format.space_after=Pt(6)
    normal.paragraph_format.line_spacing=1.07
    for name,size in [('Title',27),('Heading 1',18),('Heading 2',12)]:
        st=doc.styles[name];st.font.name='Arial';st.font.size=Pt(size);st.font.color.rgb=RGBColor.from_string(NAVY[1:])
    header=sec.header.paragraphs[0];header.text='И-ГЦ-02   /   ПРОЕКТЫ СОП   /   НЕ УТВЕРЖДЕНО';header.style='Caption'
    foot=sec.footer.paragraphs[0];foot.text='Статический снимок ДЕМО. Актуальные числа после изменений — в Excel.  |  '
    fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');foot._p.append(fld)
    def paragraph(text,style=None):return doc.add_paragraph(text,style)
    def title(text):doc.add_heading(text,level=1)
    def table(labels,rows,widths=None):
        t=doc.add_table(rows=1, cols=len(labels));t.style='Table Grid'
        for i,l in enumerate(labels):
            c=t.rows[0].cells[i];c.text=l;shade(c,'246577')
            for run in c.paragraphs[0].runs:run.font.color.rgb=RGBColor(255,255,255);run.bold=True
        repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
        for row in rows:
            cells=t.add_row().cells
            for i,v in enumerate(row):cells[i].text=str(v)
            for cell in cells:
                for p in cell.paragraphs:
                    p.paragraph_format.space_after=Pt(3);p.paragraph_format.space_before=Pt(3)
                    for run in p.runs:run.font.size=Pt(9)
            trPr=t.rows[-1]._tr.get_or_add_trPr();no=OxmlElement('w:cantSplit');trPr.append(no)
        if widths:
            t.autofit=False
            for row in t.rows:
                for cell,width in zip(row.cells,widths):cell.width=Cm(width)
        paragraph('')
        return t
    doc.add_heading('Обработка овощей,\nлистовых салатов\nи зелени',0)
    paragraph('Проекты стандартов операционных процедур\nна основе И-ГЦ-02 и МУ-41-2024', 'Subtitle')
    paragraph('Версия расчётного примера: 05.09.2026')
    table(['Поле','Состояние проекта'],[
        ['Предприятие','АО «ПП «Русский хлеб» — реквизиты сверить: на титуле И-ГЦ-02 также указано ООО «Курортное кафе».'],
        ['Цех / участок','Кулинарный цех / овощной участок, SOLIA — уточнить.'],
        ['Разработал / согласовал','Роли: составитель, инженер-технолог, ответственный по ОТ. ФИО внести после назначения.'],
        ['Утвердил / подписи','НЕ УТВЕРЖДЕНО. Подписи и даты утверждения не созданы.'],
        ['Статус времён','Все ручные длительности — синтетический пример. Режимы SOLIA — из И-ГЦ-02.'],
        ['Основной рабочий файл','Стандартизированная_работа_И-ГЦ-02.xlsx — 28 связанных листов.']],[5,12.5])
    title('Как использовать этот документ')
    paragraph('Это статический снимок проекта. Числа Word не обновляются при изменении Excel. Для актуальных стандартов выбирайте продукт во «Ввод!B12» и печатайте лист «СОП» из книги. Здесь приведены два примера маршрута — томат и латук — и общий периодический санитарный комплекс. Для остальных видов используются собственные замеры в Excel.')
    paragraph('До внедрения необходимо проверить паспорт SOLIA, действующие санитарные документы и инструкции ОТ, уточнить СИЗ, фото ОК/NOK и критерии контроля, провести наблюдения, согласовать и утвердить стандарты, обучить сотрудников. Пример не является подтверждением внедрения или безопасности.')
